        db.execute('CREATE TABLE IF NOT EXISTS job_batches(batch TEXT PRIMARY KEY,project TEXT,location TEXT,job_id TEXT,configuration TEXT,last_state TEXT)')
        row=db.execute('SELECT project,location,job_id,configuration FROM job_batches WHERE batch=?',(batch,)).fetchone()
