            job_id='opsforge_'+uuid.uuid4().hex
            db.execute('INSERT INTO job_batches VALUES(?,?,?,?,?,?)',(batch,project,location,job_id,encoded,'unknown'))
        else:
            if (row[0],row[1],row[3])!=(project,location,encoded):raise ValueError('batch identity or configuration conflict')
            job_id=row[2]
    # Mapping commits before a request may escape; a retry can only reuse this exact identity.
    reference={'projectId':project,'location':location,'jobId':job_id}
