        with sqlite3.connect(path,timeout=2) as db:db.execute('UPDATE job_batches SET last_state=? WHERE batch=?',(state,batch))
        return {'jobReference':dict(reference),'state':state}
    try:code,job=api('insert',dict(reference),dict(configuration))
    except TimeoutError:code,job=0,None
    if code==403:return finish('blocked')
    if code not in (200,201):
        if code not in (0,409,500,502,503,504):return finish('unknown')
        try:code,job=api('get',dict(reference),None)
        except TimeoutError:return finish('unknown')
        if code==403:return finish('blocked')
        if code!=200:return finish('unknown')
    if not isinstance(job,dict) or job.get('jobReference')!=reference or job.get('configuration')!=configuration:return finish('unknown')
    status=job.get('status',{})
    if status.get('state')=='PENDING':return finish('pending')
    if status.get('state')=='RUNNING':return finish('running')
    if status.get('state')!='DONE':return finish('unknown')
    if status.get('errorResult') is not None:return finish('failed')
    try:verified=verify_output(job)
    except (OSError,TimeoutError):return finish('unknown')
    return finish('succeeded' if verified is True else 'reconcile')
